WITH matched_keys AS (SELECT plan FROM subscriptions EXCEPT ALL SELECT plan FROM subscriptions WHERE plan = 'basic'), reconciled AS (SELECT s.* FROM subscriptions s INNER JOIN matched_keys k ON s.plan = k.plan), valid AS (SELECT id, customer_id, start_date, monthly_fee, status, LOWER(plan) AS plan_lower FROM reconciled WHERE end_date > TO_DATE('2023-10-22')), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY customer_id, status ORDER BY monthly_fee DESC) AS monthly_fee_dense_rank, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY customer_id), 4) AS monthly_fee_share FROM valid), enriched AS (SELECT s.id, s.customer_id, s.start_date, s.monthly_fee, s.plan_lower, s.monthly_fee_dense_rank, s.monthly_fee_share, p.segment, p.signup_date, p.country FROM metrics s LEFT JOIN customers p ON s.customer_id = p.id WHERE p.city <> 'Tokyo'), valid_subscriptions AS (SELECT *, monthly_fee_share * monthly_fee_dense_rank AS monthly_fee_share_times_monthly_fee_dense_rank, LEAST(monthly_fee, monthly_fee_share) AS least_monthly_fee_monthly_fee_share, COALESCE(segment, 'UNKNOWN') AS resolved_segment FROM enriched WHERE start_date >= DATE '2023-09-12'), with_dims AS (SELECT a.*, p.email, p.segment AS customer_segment, p.age FROM valid_subscriptions a LEFT JOIN customers p ON a.customer_id <=> p.id), totals AS (SELECT CASE WHEN monthly_fee >= 224 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_tier, CASE WHEN monthly_fee_share >= 0.69 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_share_tier, SUM(CASE WHEN country = 'US' THEN monthly_fee ELSE 0 END) AS us_monthly_fee, AVG(least_monthly_fee_monthly_fee_share) FILTER (WHERE segment = 'SMB') AS smb_avg_least_monthly_fee_monthly_fee_share, SUM(CASE WHEN customer_segment = 'Consumer' THEN monthly_fee ELSE 0 END) AS consumer_monthly_fee, RANK() OVER (PARTITION BY CASE WHEN monthly_fee >= 224 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY SUM(CASE WHEN customer_segment = 'Consumer' THEN monthly_fee ELSE 0 END) DESC) AS consumer_monthly_fee_rank FROM with_dims GROUP BY 1, 2) SELECT monthly_fee_tier, monthly_fee_share_tier, consumer_monthly_fee, consumer_monthly_fee_rank FROM totals;
